 main='<main id="main" tabindex="-1" class="svx-main svx-'+d['accent']+'" data-special-service="'+d['slug']+'">'+nav+hero+outputs+prep+steps+faq+end+'</main>'
 # Keep service metadata; align visible FAQ and separate practice offers with canonical routes.
 schemas=''
